'use client';

import React, { useMemo, useState } from 'react';
import { Bar, BarChart, CartesianGrid, Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { Order, OrderActivity, OrderNote, OrderStatus, PaymentStatus, Deal, Customer, User } from '../../types/index.ts';
import { calculateOrderTotals, getNextOrderStatuses, getPaymentStatus } from './orderMath.ts';
import { OrderForm } from './OrderForm.tsx';
import { formatDate } from '../../lib/utils.ts';
import { toast } from '../ui/Sonner.tsx';
import { Badge } from '../ui/Badge.tsx';
import { Button } from '../ui/Button.tsx';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/Card.tsx';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '../ui/Dialog.tsx';
import { Input } from '../ui/Input.tsx';
import { Select } from '../ui/Select.tsx';
import { Activity, ArrowLeft, ArrowRight, Banknote, BarChart3, Building, CalendarDays, Check, ChevronRight, CircleDollarSign, Clock3, Download, FileText, Filter, PackageCheck, Pencil, Plus, Printer, Search, ShoppingBag, Truck, UserRound, Users, Wallet, X } from 'lucide-react';

interface OrderWorkspaceProps {
  orders: Order[];
  customers: Customer[];
  deals: Deal[];
  users: User[];
  currentUser: User;
  selectedOrderId?: string | null;
  isLoading?: boolean;
  error?: string | null;
  onOrdersChange: (orders: Order[]) => void;
  onNavigate: (path: string, id?: string) => void;
  onAddCustomer: () => void;
}

type OrderFilters = { status: string; payment: string; customer: string; salesperson: string; dateFrom: string; dateTo: string; minAmount: string; maxAmount: string; delivery: string };
const EMPTY_FILTERS: OrderFilters = { status: '', payment: '', customer: '', salesperson: '', dateFrom: '', dateTo: '', minAmount: '', maxAmount: '', delivery: '' };
const MONEY = (value: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 }).format(value);
const csvCell = (value: unknown) => `"${String(value ?? '').replaceAll('"', '""')}"`;
const statusLabels: Record<OrderStatus, string> = { DRAFT: 'Draft', PENDING: 'Pending', CONFIRMED: 'Confirmed', PROCESSING: 'Processing', READY: 'Ready', COMPLETED: 'Completed', CANCELLED: 'Cancelled', REFUNDED: 'Refunded' };
const paymentLabels: Record<PaymentStatus, string> = { UNPAID: 'Unpaid', PARTIAL: 'Partial', PAID: 'Paid', OVERDUE: 'Overdue', REFUNDED: 'Refunded' };
const deliveryLabels: Record<Order['deliveryStatus'], string> = { NOT_STARTED: 'Not started', PROCESSING: 'Processing', READY: 'Ready', SHIPPED: 'Shipped', DELIVERED: 'Delivered', FAILED: 'Failed' };
const statusVariant = (status: OrderStatus) => status === 'COMPLETED' ? 'success' : status === 'CANCELLED' ? 'destructive' : status === 'REFUNDED' ? 'secondary' : status === 'PROCESSING' || status === 'READY' ? 'cyan' : status === 'CONFIRMED' ? 'default' : 'warning';
const paymentVariant = (status: PaymentStatus) => status === 'PAID' ? 'success' : status === 'OVERDUE' ? 'destructive' : status === 'REFUNDED' ? 'secondary' : status === 'PARTIAL' ? 'warning' : 'outline';

function Metric({ label, value, detail, icon: Icon, tone }: { label: string; value: string; detail: string; icon: React.ElementType; tone: string }) {
  return <Card><CardContent className="flex items-start justify-between gap-2 p-3.5"><div className="min-w-0"><p className="text-[11px] font-medium text-slate-500 dark:text-slate-400">{label}</p><p className="mt-1 text-xl font-bold text-slate-900 dark:text-white">{value}</p><p className="mt-1 truncate text-[10px] text-slate-400">{detail}</p></div><span className={`rounded-md p-2 ${tone}`}><Icon className="h-4 w-4" /></span></CardContent></Card>;
}

export function OrderWorkspace({ orders, customers, deals, users, currentUser, selectedOrderId = null, isLoading = false, error, onOrdersChange, onNavigate, onAddCustomer }: OrderWorkspaceProps) {
  const [formOpen, setFormOpen] = useState(false);
  const [editingOrder, setEditingOrder] = useState<Order | null>(null);
  const [seedDeal, setSeedDeal] = useState<Deal | null>(null);
  const [search, setSearch] = useState('');
  const [filterOpen, setFilterOpen] = useState(false);
  const [draftFilters, setDraftFilters] = useState<OrderFilters>(EMPTY_FILTERS);
  const [filters, setFilters] = useState<OrderFilters>(EMPTY_FILTERS);
  const [selected, setSelected] = useState<string[]>([]);
    const [bulkStatus, setBulkStatus] = useState('');
  const [dateRange, setDateRange] = useState<'7d' | '30d' | '3m' | '6m' | '1y'>('30d');
  const [cancelOrder, setCancelOrder] = useState<Order | null>(null);
  const [cancelReason, setCancelReason] = useState('');
  const [cancelNotes, setCancelNotes] = useState('');
  const [refundOrder, setRefundOrder] = useState<Order | null>(null);
  const [refundAmount, setRefundAmount] = useState('');
  const [refundReason, setRefundReason] = useState('');
  const [paymentOrder, setPaymentOrder] = useState<Order | null>(null);
  const [paymentAmount, setPaymentAmount] = useState('');
  const [paymentMethod, setPaymentMethod] = useState('Bank transfer');
  const [paymentTransaction, setPaymentTransaction] = useState('');
  const [noteOrder, setNoteOrder] = useState<Order | null>(null);
  const [noteText, setNoteText] = useState('');
  const [editingNoteId, setEditingNoteId] = useState<string | null>(null);
  const [transitionOrder, setTransitionOrder] = useState<Order | null>(null);
  const [transitionStatus, setTransitionStatus] = useState<OrderStatus | null>(null);
  const [bulkCancelOpen, setBulkCancelOpen] = useState(false);

  const customerById = (id: string) => customers.find((customer) => customer.id === id);
  const dealById = (id?: string | null) => deals.find((deal) => deal.id === id);
  const userById = (id?: string | null) => users.find((user) => user.id === id);
  const orderTotals = (order: Order) => calculateOrderTotals(order.items || [], order.additionalCharges || 0, order.paidAmount || 0);
  const paymentStatus = (order: Order) => order.status === 'REFUNDED' || (order.refundAmount || 0) >= order.total ? 'REFUNDED' : getPaymentStatus(order.total, order.paidAmount, order.paymentDueDate);
  const selectedOrder = orders.find((order) => order.id === selectedOrderId) || null;
  const inRange = (value: Date | string, from: string, to: string) => {
    const time = new Date(value).getTime();
    return (!from || time >= new Date(from).getTime()) && (!to || time <= new Date(`${to}T23:59:59`).getTime());
  };

  const filtered = useMemo(() => {
    const needle = search.trim().toLowerCase();
    return orders.filter((order) => {
      const customer = customerById(order.customerId);
      const deal = dealById(order.dealId);
      const salesperson = userById(order.salespersonId);
      const matchesSearch = !needle || [order.id, customer?.name, order.company, deal?.title, customer?.email, customer?.phone].some((value) => value?.toLowerCase().includes(needle));
      const paid = paymentStatus(order);
      return matchesSearch
        && (!filters.status || order.status === filters.status)
        && (!filters.payment || paid === filters.payment)
        && (!filters.customer || order.customerId === filters.customer)
        && (!filters.salesperson || order.salespersonId === filters.salesperson)
        && (!filters.delivery || order.deliveryStatus === filters.delivery)
        && (!filters.minAmount || order.total >= Number(filters.minAmount))
        && (!filters.maxAmount || order.total <= Number(filters.maxAmount))
        && (!filters.dateFrom && !filters.dateTo || inRange(order.orderDate, filters.dateFrom, filters.dateTo))
        && (!needle || Boolean(customer || deal || salesperson) || matchesSearch);
    });
  }, [orders, customers, deals, users, filters, search]);

  const metrics = useMemo(() => {
    const sum = (status?: OrderStatus) => orders.filter((order) => !status || order.status === status).reduce((total, order) => total + order.total, 0);
    return {
      total: orders.length,
      newCount: orders.filter((order) => order.status === 'DRAFT' || order.status === 'PENDING').length,
      processing: orders.filter((order) => ['CONFIRMED', 'PROCESSING', 'READY'].includes(order.status)).length,
      completed: orders.filter((order) => order.status === 'COMPLETED').length,
      pending: orders.filter((order) => order.status === 'PENDING').length,
      cancelled: orders.filter((order) => order.status === 'CANCELLED').length,
      value: sum(),
      outstanding: orders.filter((order) => !['CANCELLED', 'REFUNDED'].includes(order.status)).reduce((total, order) => total + order.remainingAmount, 0),
    };
  }, [orders]);

  const analytics = useMemo(() => {
    const days = { '7d': 7, '30d': 30, '3m': 90, '6m': 180, '1y': 365 }[dateRange];
    const recent = orders.filter((order) => Date.now() - new Date(order.orderDate).getTime() <= days * 86400000);
    const monthCount = Math.min(6, Math.max(2, Math.ceil(days / 30)));
    const byMonth = Array.from({ length: monthCount }, (_, index) => {
      const month = new Date(); month.setDate(1); month.setMonth(month.getMonth() - monthCount + index + 1);
      const key = `${month.getFullYear()}-${month.getMonth()}`;
      const monthOrders = recent.filter((order) => { const date = new Date(order.orderDate); return `${date.getFullYear()}-${date.getMonth()}` === key; });
      return { month: month.toLocaleDateString(undefined, { month: 'short' }), count: monthOrders.length, value: monthOrders.reduce((sum, order) => sum + order.total, 0) };
    });
    return {
      byMonth,
      statuses: ['COMPLETED', 'CANCELLED'].map((status) => ({ name: statusLabels[status as OrderStatus], value: orders.filter((order) => order.status === status).length })),
      payments: ['UNPAID', 'PARTIAL', 'PAID', 'OVERDUE', 'REFUNDED'].map((status) => ({ name: paymentLabels[status as PaymentStatus], value: orders.filter((order) => paymentStatus(order) === status).length })),
      average: recent.length ? recent.reduce((sum, order) => sum + order.total, 0) / recent.length : 0,
      recentCount: recent.length,
    };
  }, [orders, dateRange]);

  const pushOrder = (order: Order) => onOrdersChange([order, ...orders]);
  const updateOrder = (id: string, updates: Partial<Order>, event?: Omit<OrderActivity, 'id' | 'createdAt' | 'user'>) => {
    const now = new Date();
    onOrdersChange(orders.map((order) => order.id !== id ? order : {
      ...order, ...updates, updatedAt: now, lastActivityAt: now,
      activities: event ? [{ id: `oa_${Date.now()}`, ...event, user: currentUser.name, createdAt: now }, ...(order.activities || [])] : order.activities,
    }));
  };

  const saveNewOrder = async (data: any) => {
    const now = new Date();
    const totals = calculateOrderTotals(data.items, data.additionalCharges, data.paidAmount);
    const order: Order = {
      ...data, ...totals, id: `ORD-${now.getFullYear()}-${String(now.getTime()).slice(-6)}`, organizationId: currentUser.organizationId,
      paymentStatus: getPaymentStatus(totals.total, totals.paidAmount), deliveryStatus: data.deliveryStatus || 'NOT_STARTED',
      notes: data.notes?.trim() ? [{ id: `note_${Date.now()}`, content: data.notes.trim(), author: currentUser.name, createdAt: now }] : [],
      activities: [{ id: `oa_${Date.now()}`, type: 'CREATED', description: 'Order created', user: currentUser.name, createdAt: now }],
      invoiceReferences: [], paymentReferences: [], refundAmount: 0, refundStatus: 'NONE', createdAt: now, updatedAt: now, lastActivityAt: now,
    };
    pushOrder(order);
    toast.success(order.sourceDealHandoffId ? 'Order created from won deal handoff' : 'Order created');
  };

  const saveOrderEdit = async (data: any) => {
    if (!editingOrder) return;
    const { notes: noteTextValue, ...editable } = data;
    const totals = calculateOrderTotals(editable.items, editable.additionalCharges, editable.paidAmount);
    const notes = noteTextValue?.trim() ? [{ id: `on_${Date.now()}`, content: noteTextValue.trim(), author: currentUser.name, createdAt: new Date() }, ...editingOrder.notes] : editingOrder.notes;
    updateOrder(editingOrder.id, { ...editable, ...totals, notes, paymentStatus: getPaymentStatus(totals.total, totals.paidAmount, editable.paymentDueDate) }, { type: 'UPDATED', description: 'Order details updated' });
    toast.success('Order updated');
  };

  const duplicateOrder = (order: Order) => {
    setEditingOrder(null); setSeedDeal(null);
    setDuplicateSeed({ ...order, id: `copy_${Date.now()}`, status: 'DRAFT', paidAmount: 0, remainingAmount: order.total, paymentStatus: 'UNPAID', notes: [], activities: [], invoiceReferences: [], paymentReferences: [], sourceDealHandoffId: null, cancellationReason: null, cancellationNotes: null, refundAmount: 0, refundDate: null, refundReason: null, refundStatus: 'NONE' });
    setFormOpen(true);
  };
  const [duplicateSeed, setDuplicateSeed] = useState<Order | null>(null);
  const openCreate = (deal?: Deal | null) => { setEditingOrder(null); setDuplicateSeed(null); setSeedDeal(deal || null); setFormOpen(true); };
  const openEdit = (order: Order) => {
    if (['COMPLETED', 'CANCELLED', 'REFUNDED'].includes(order.status)) {
      toast.info('Completed, cancelled, or refunded orders are read-only');
      return;
    }
    setDuplicateSeed(null); setSeedDeal(null); setEditingOrder(order); setFormOpen(true);
  };

  const exportOrders = () => {
    const exportRows = [['Order ID', 'Customer', 'Salesperson', 'Amount', 'Paid', 'Remaining', 'Payment Status', 'Order Status', 'Date']];
    (selected.length ? filtered.filter((order) => selected.includes(order.id)) : filtered).forEach((order) => exportRows.push([
      order.id, customerById(order.customerId)?.name || '', userById(order.salespersonId)?.name || '', String(order.total), String(order.paidAmount), String(order.remainingAmount), paymentStatus(order), order.status, formatDate(order.orderDate),
    ]));
    const url = URL.createObjectURL(new Blob([`\ufeff${exportRows.map((row) => row.map(csvCell).join(',')).join('\r\n')}`], { type: 'text/csv;charset=utf-8' }));
    const link = document.createElement('a'); link.href = url; link.download = 'orders.csv'; link.click(); URL.revokeObjectURL(url);
  };

  const selectedOrderIds = selectedOrder;
  const renderDetails = (order: Order) => {
    const customer = customerById(order.customerId);
    const deal = dealById(order.dealId);
    const allowed = getNextOrderStatuses(order.status);
    const addInvoice = () => updateOrder(order.id, { invoiceReferences: [{ id: `INV-DRAFT-${Date.now()}`, amount: order.remainingAmount, status: 'DRAFT', createdAt: new Date() }, ...(order.invoiceReferences || [])] }, { type: 'INVOICE_CREATED', description: 'Draft invoice reference created' });
    const addNote = () => {
      const content = noteText.trim(); if (!content) return;
      const notes = editingNoteId ? order.notes.map((note) => note.id === editingNoteId ? { ...note, content } : note) : [{ id: `on_${Date.now()}`, content, author: currentUser.name, createdAt: new Date() }, ...order.notes];
      updateOrder(order.id, { notes }, { type: 'NOTE_ADDED', description: editingNoteId ? 'Order note updated' : 'Order note added' });
      setNoteText(''); setEditingNoteId(null); setNoteOrder(null);
    };
    const submitPayment = () => {
      const amount = Number(paymentAmount);
      if (!Number.isFinite(amount) || amount <= 0 || amount > order.remainingAmount) return;
      const now = new Date(); const reference = { id: `PAY-LOCAL-${Date.now()}`, amount, method: paymentMethod, transactionId: paymentTransaction, status: 'RECORDED' as const, paidAt: now };
      const paid = Math.min(order.total, order.paidAmount + amount);
      updateOrder(order.id, { paymentReferences: [reference, ...(order.paymentReferences || [])], paidAmount: paid, remainingAmount: order.total - paid, paymentStatus: getPaymentStatus(order.total, paid, order.paymentDueDate), lastPaymentDate: now }, { type: 'PAYMENT_RECEIVED', description: `${MONEY(amount)} payment recorded` });
      setPaymentOrder(null); setPaymentAmount(''); setPaymentTransaction('');
    };
    const beginRefund = () => { setRefundAmount(String(order.paidAmount)); setRefundReason(''); setRefundOrder(order); };
    const submitRefund = () => {
      if (!refundOrder || refundOrder.id !== order.id) return;
      const amount = Number(refundAmount);
      if (!Number.isFinite(amount) || amount <= 0 || amount > order.paidAmount || !refundReason.trim()) return;
      const now = new Date();
      const refundedTotal = (order.refundAmount || 0) + amount;
      const fullRefund = refundedTotal >= order.total;
      const paidAmount = Math.max(0, order.paidAmount - amount);
      updateOrder(order.id, { status: fullRefund ? 'REFUNDED' : order.status, paidAmount, remainingAmount: Math.max(0, order.total - paidAmount), refundAmount: refundedTotal, refundDate: now, refundReason, refundStatus: 'COMPLETED', paymentStatus: fullRefund ? 'REFUNDED' : getPaymentStatus(order.total, paidAmount, order.paymentDueDate) }, { type: 'REFUNDED', description: `${MONEY(amount)} refund recorded: ${refundReason}` });
      setRefundOrder(null);
    };

    return <div className="space-y-5">
      <div className="flex flex-wrap items-center justify-between gap-3"><Button variant="ghost" onClick={() => onNavigate('/orders')}><ArrowLeft className="mr-1.5 h-4 w-4" />Orders</Button><div className="flex flex-wrap gap-2">{!['CANCELLED', 'REFUNDED', 'COMPLETED'].includes(order.status) && <Button size="sm" variant="outline" onClick={() => openEdit(order)}><Pencil className="mr-1 h-4 w-4" />Edit</Button>}<Button size="sm" variant="outline" onClick={addInvoice}><FileText className="mr-1 h-4 w-4" />Create invoice</Button><Button size="sm" variant="outline" onClick={() => setPaymentOrder(order)}><Banknote className="mr-1 h-4 w-4" />Record payment</Button><Button size="sm" variant="outline" onClick={() => window.print()}><Printer className="mr-1 h-4 w-4" />Print / PDF</Button>{order.status === 'COMPLETED' && order.paidAmount > 0 && <Button size="sm" variant="outline" onClick={beginRefund}>Refund</Button>}{!['CANCELLED', 'REFUNDED', 'COMPLETED'].includes(order.status) && <Button size="sm" variant="destructive" onClick={() => { setCancelOrder(order); setCancelReason(''); setCancelNotes(''); }}>Cancel order</Button>}</div></div>
      <div className="rounded-lg border border-slate-200 bg-white p-4 dark:border-slate-800 dark:bg-slate-900"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex flex-wrap items-center gap-2"><h1 className="text-xl font-bold text-slate-900 dark:text-white">{order.id}</h1><Badge variant={statusVariant(order.status)}>{statusLabels[order.status]}</Badge><Badge variant={paymentVariant(paymentStatus(order))}>{paymentLabels[paymentStatus(order)]}</Badge></div><p className="mt-1 text-sm text-slate-500">{customer?.name || 'Customer'} · {order.company || customer?.company || 'Company not set'}</p></div><div className="text-left sm:text-right"><p className="text-xs text-slate-400">Order total</p><p className="text-xl font-bold text-slate-900 dark:text-white">{MONEY(order.total)}</p></div></div><div className="mt-3 flex flex-wrap items-center gap-2">{allowed.filter((next) => next !== 'CANCELLED').map((next) => <Button size="sm" key={next} variant="outline" onClick={() => { setTransitionOrder(order); setTransitionStatus(next); }}>Move to {statusLabels[next]}<ChevronRight className="ml-1 h-3.5 w-3.5" /></Button>)}{allowed.includes('CANCELLED') && <Button size="sm" variant="destructive" onClick={() => confirmCancel(order)}>Cancel order</Button>}{order.status === 'COMPLETED' && <Button size="sm" variant="outline" onClick={beginRefund}>Record refund</Button>}</div></div>

      <div className="grid grid-cols-2 gap-3 md:grid-cols-4"><Summary label="Order total" value={MONEY(order.total)} icon={ShoppingBag} /><Summary label="Paid" value={MONEY(order.paidAmount)} icon={Check} /><Summary label="Remaining" value={MONEY(order.remainingAmount)} icon={Wallet} /><Summary label="Order date" value={formatDate(order.orderDate)} icon={CalendarDays} /></div>
      <div className="grid grid-cols-1 gap-4 xl:grid-cols-3">
        <Card className="xl:col-span-2"><CardHeader><CardTitle className="text-base">Order items</CardTitle></CardHeader><CardContent><SimpleTable headers={['Item', 'Description', 'Quantity', 'Unit price', 'Discount', 'Tax', 'Total']} rows={order.items.map((item) => { const amount = calculateOrderTotals([item], 0, 0); return [item.name, item.description || '—', String(item.quantity), MONEY(item.unitPrice), `${item.discount}%`, `${item.tax}%`, MONEY(amount.total)]; })} empty="This order has no items." /></CardContent></Card>
        <Card><CardHeader><CardTitle className="text-base">Customer</CardTitle></CardHeader><CardContent>{customer ? <div className="space-y-2 text-sm"><button onClick={() => onNavigate('/customers/detail', customer.id)} className="font-semibold text-indigo-600 hover:underline">{customer.name}</button><p className="text-slate-500">{order.company || customer.company || '—'}</p><p className="text-slate-500">{customer.email || 'No email'}</p><p className="text-slate-500">{customer.phone || 'No phone'}</p><p className="text-slate-500">{[customer.address, customer.city, customer.state, customer.postalCode, customer.country].filter(Boolean).join(', ') || order.deliveryAddress || 'No address'}</p><Button size="sm" variant="outline" onClick={() => onNavigate('/customers/detail', customer.id)}>Customer 360</Button></div> : <Empty text="Customer record is unavailable." />}</CardContent></Card>
        <Card><CardHeader><CardTitle className="text-base">Deal information</CardTitle></CardHeader><CardContent>{deal ? <div className="space-y-2 text-sm"><button onClick={() => onNavigate('/deals/detail', deal.id)} className="text-left font-semibold text-indigo-600 hover:underline">{deal.title}</button><p className="text-slate-500">{deal.stage} · {MONEY(deal.value)}</p><p className="text-slate-500">{userById(deal.assignedToId)?.name || 'Unassigned'}</p><Pair label="Expected close" value={deal.expectedCloseDate ? formatDate(deal.expectedCloseDate) : '—'} /><Button size="sm" variant="outline" onClick={() => onNavigate('/deals/detail', deal.id)}>Open deal</Button></div> : <Empty text="No related deal." />}</CardContent></Card>
        <Card><CardHeader><CardTitle className="text-base">Payment summary</CardTitle></CardHeader><CardContent className="space-y-2 text-sm"><Pair label="Order total" value={MONEY(order.total)} /><Pair label="Paid" value={MONEY(order.paidAmount)} /><Pair label="Remaining" value={MONEY(order.remainingAmount)} /><Pair label="Payment status" value={paymentLabels[paymentStatus(order)]} /><Pair label="Last payment" value={order.lastPaymentDate ? formatDate(order.lastPaymentDate) : '—'} /><Button className="mt-2" size="sm" variant="outline" onClick={() => setPaymentOrder(order)}>Record payment</Button>{order.paymentReferences.length > 0 && <div className="border-t border-slate-100 pt-2 dark:border-slate-800"><SimpleTable headers={['Payment ref', 'Method', 'Amount', 'Date']} rows={order.paymentReferences.map((payment) => [payment.id, payment.method, MONEY(payment.amount), formatDate(payment.paidAt)])} empty="No payments recorded." /></div>}</CardContent></Card>
        <Card><CardHeader><CardTitle className="text-base">Delivery</CardTitle></CardHeader><CardContent className="space-y-2 text-sm"><Pair label="Status" value={deliveryLabels[order.deliveryStatus]} /><Pair label="Expected" value={order.expectedDelivery ? formatDate(order.expectedDelivery) : '—'} /><Pair label="Delivered" value={order.deliveryDate ? formatDate(order.deliveryDate) : '—'} /><Pair label="Shipping method" value={order.shippingMethod || '—'} /><Pair label="Tracking" value={order.trackingNumber || '—'} /><Pair label="Address" value={order.deliveryAddress || '—'} /><Pair label="Notes" value={order.deliveryNotes || '—'} /></CardContent></Card>
        <Card><CardHeader><CardTitle className="text-base">Pricing</CardTitle></CardHeader><CardContent className="space-y-2 text-sm"><Pair label="Subtotal" value={MONEY(order.subtotal)} /><Pair label="Discount" value={`−${MONEY(order.discount)}`} /><Pair label="Tax" value={MONEY(order.tax)} /><Pair label="Additional charges" value={MONEY(order.additionalCharges)} /><Pair label="Total" value={MONEY(order.total)} bold /></CardContent></Card>
        <Card className="xl:col-span-2"><CardHeader><CardTitle className="text-base">Order timeline</CardTitle></CardHeader><CardContent><Timeline events={order.activities} /></CardContent></Card>
        <Card><CardHeader><CardTitle className="text-base">Invoices</CardTitle></CardHeader><CardContent className="space-y-3">{order.invoiceReferences.length ? order.invoiceReferences.map((invoice) => <div key={invoice.id} className="flex items-center justify-between text-sm"><span>{invoice.id}</span><span>{MONEY(invoice.amount)}</span><Badge variant="outline">{invoice.status}</Badge></div>) : <Empty text="No invoice references yet." />}<Button size="sm" variant="outline" onClick={addInvoice}><FileText className="mr-1 h-4 w-4" />Create invoice</Button></CardContent></Card>
        <Card className="xl:col-span-3"><CardHeader><CardTitle className="text-base">Order notes</CardTitle></CardHeader><CardContent className="space-y-3"><div className="flex flex-col gap-2 sm:flex-row"><Input value={noteText} onChange={(event) => setNoteText(event.target.value)} placeholder={editingNoteId ? 'Edit note' : 'Add a note to this order'} /><Button size="sm" disabled={!noteText.trim()} onClick={addNote}><Plus className="mr-1 h-4 w-4" />{editingNoteId ? 'Save note' : 'Add note'}</Button></div>{order.notes.map((note) => <div key={note.id} className="flex items-start justify-between gap-3 rounded-md border border-slate-100 p-3 dark:border-slate-800"><div><p className="whitespace-pre-wrap text-sm">{note.content}</p><p className="mt-1 text-xs text-slate-400">{note.author} · {new Date(note.createdAt).toLocaleString()}</p></div><div className="flex"><Button size="icon" variant="ghost" title="Edit note" onClick={() => { setEditingNoteId(note.id); setNoteText(note.content); }}><Pencil className="h-4 w-4" /></Button><Button size="icon" variant="ghost" title="Delete note" onClick={() => updateOrder(order.id, { notes: order.notes.filter((item) => item.id !== note.id) }, { type: 'NOTE_ADDED', description: 'Order note deleted' })}><X className="h-4 w-4 text-rose-500" /></Button></div></div>)}</CardContent></Card>
      </div>

      <Dialog open={Boolean(transitionOrder && transitionStatus)} onOpenChange={(open) => { if (!open) { setTransitionOrder(null); setTransitionStatus(null); } }}><DialogContent><DialogHeader onClose={() => { setTransitionOrder(null); setTransitionStatus(null); }}><DialogTitle>Change order status</DialogTitle><DialogDescription>Move {order.id} from {statusLabels[order.status]} to {transitionStatus ? statusLabels[transitionStatus] : ''}?</DialogDescription></DialogHeader><p className="text-sm text-slate-600 dark:text-slate-300">This status transition will be recorded in the order timeline.</p><DialogFooter><Button variant="outline" onClick={() => { setTransitionOrder(null); setTransitionStatus(null); }}>Keep current status</Button><Button onClick={() => { if (!transitionStatus) return; const next = transitionStatus; updateOrder(order.id, { status: next, paymentStatus: next === 'REFUNDED' ? 'REFUNDED' : order.paymentStatus }, { type: next === 'CONFIRMED' ? 'CONFIRMED' : next === 'PROCESSING' ? 'PROCESSING' : next === 'READY' ? 'READY' : next === 'COMPLETED' ? 'COMPLETED' : 'UPDATED', description: `Order status changed to ${statusLabels[next]}` }); setTransitionOrder(null); setTransitionStatus(null); }}>Confirm change</Button></DialogFooter></DialogContent></Dialog>
      <Dialog open={Boolean(cancelOrder)} onOpenChange={(open) => { if (!open) setCancelOrder(null); }}><DialogContent><DialogHeader onClose={() => setCancelOrder(null)}><DialogTitle>Cancel order</DialogTitle><DialogDescription>Cancellation is permanent for fulfillment, but order history will be retained.</DialogDescription></DialogHeader><label className="block space-y-1 text-xs font-medium text-slate-600 dark:text-slate-300">Reason *<Select value={cancelReason} onChange={(event) => setCancelReason(event.target.value)}><option value="">Select reason</option>{['Customer Request', 'Payment Issue', 'Stock/Availability', 'Duplicate Order', 'Other'].map((reason) => <option key={reason}>{reason}</option>)}</Select></label><label className="block space-y-1 text-xs font-medium text-slate-600 dark:text-slate-300">Additional notes<textarea rows={3} value={cancelNotes} onChange={(event) => setCancelNotes(event.target.value)} className="w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm dark:border-slate-800 dark:bg-slate-900" /></label><DialogFooter><Button variant="outline" onClick={() => setCancelOrder(null)}>Keep order</Button><Button variant="destructive" disabled={!cancelReason} onClick={() => { if (!cancelOrder || !cancelReason) return; updateOrder(cancelOrder.id, { status: 'CANCELLED', cancellationReason: cancelReason, cancellationNotes: cancelNotes }, { type: 'CANCELLED', description: `Order cancelled: ${cancelReason}${cancelNotes ? ` · ${cancelNotes}` : ''}` }); setCancelOrder(null); }}>Confirm cancellation</Button></DialogFooter></DialogContent></Dialog>
      <Dialog open={Boolean(refundOrder)} onOpenChange={(open) => { if (!open) setRefundOrder(null); }}><DialogContent><DialogHeader onClose={() => setRefundOrder(null)}><DialogTitle>Record refund</DialogTitle><DialogDescription>This records a refund against this completed order; no payment gateway is connected.</DialogDescription></DialogHeader><Field label="Refund amount"><Input type="number" min="0.01" max={refundOrder?.paidAmount || 0} step="0.01" value={refundAmount} onChange={(event) => setRefundAmount(event.target.value)} /></Field><Field label="Refund reason"><Input value={refundReason} onChange={(event) => setRefundReason(event.target.value)} placeholder="Reason for refund" /></Field><DialogFooter><Button variant="outline" onClick={() => setRefundOrder(null)}>Cancel</Button><Button variant="destructive" disabled={!refundReason.trim() || Number(refundAmount) <= 0 || Number(refundAmount) > (refundOrder?.paidAmount || 0)} onClick={submitRefund}>Confirm refund</Button></DialogFooter></DialogContent></Dialog>
      <Dialog open={Boolean(paymentOrder)} onOpenChange={(open) => { if (!open) setPaymentOrder(null); }}><DialogContent><DialogHeader onClose={() => setPaymentOrder(null)}><DialogTitle>Record payment</DialogTitle><DialogDescription>Record an offline payment and update the order balance.</DialogDescription></DialogHeader><Field label="Amount"><Input type="number" min="0.01" max={paymentOrder?.remainingAmount || 0} step="0.01" value={paymentAmount} onChange={(event) => setPaymentAmount(event.target.value)} /></Field><Field label="Payment method"><Select value={paymentMethod} onChange={(event) => setPaymentMethod(event.target.value)}>{['Bank transfer', 'Credit card', 'Cash', 'Check', 'Other'].map((method) => <option key={method}>{method}</option>)}</Select></Field><Field label="Transaction reference"><Input value={paymentTransaction} onChange={(event) => setPaymentTransaction(event.target.value)} /></Field><DialogFooter><Button variant="outline" onClick={() => setPaymentOrder(null)}>Cancel</Button><Button disabled={!paymentAmount || Number(paymentAmount) <= 0 || Number(paymentAmount) > (paymentOrder?.remainingAmount || 0)} onClick={submitPayment}>Record payment</Button></DialogFooter></DialogContent></Dialog>
    </div>;
  };

  const beginEdit = openEdit;
  const confirmCancel = (order: Order) => { setCancelOrder(order); setCancelReason(''); setCancelNotes(''); };
  const openNew = () => { setEditingOrder(null); setDuplicateSeed(null); setSeedDeal(null); setFormOpen(true); };

  if (selectedOrderId) {
    if (!selectedOrder) return <div className="rounded-lg border border-slate-200 bg-white px-4 py-12 text-center text-sm text-slate-500 dark:border-slate-800 dark:bg-slate-900">Order not found.</div>;
    return <>{renderDetails(selectedOrder)}<OrderForm open={formOpen} onOpenChange={(open) => { setFormOpen(open); if (!open) setEditingOrder(null); }} order={editingOrder} customers={customers} deals={deals} users={users} currentUser={currentUser} onSubmit={saveOrderEdit} />{noteOrder && <Dialog open onOpenChange={(open) => { if (!open) setNoteOrder(null); }}><DialogContent><DialogHeader onClose={() => setNoteOrder(null)}><DialogTitle>Add order note</DialogTitle><DialogDescription>Notes are stored on the order record.</DialogDescription></DialogHeader><textarea rows={4} value={noteText} onChange={(event) => setNoteText(event.target.value)} className="w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm dark:border-slate-800 dark:bg-slate-900" /><DialogFooter><Button variant="outline" onClick={() => setNoteOrder(null)}>Cancel</Button><Button disabled={!noteText.trim()} onClick={() => { const now = new Date(); updateOrder(noteOrder.id, { notes: [{ id: `on_${Date.now()}`, content: noteText.trim(), author: currentUser.name, createdAt: now }, ...noteOrder.notes] }, { type: 'NOTE_ADDED', description: 'Order note added' }); setNoteOrder(null); setNoteText(''); }}>Add note</Button></DialogFooter></DialogContent></Dialog>}</>;
  }

  const toggleSelect = (id: string) => setSelected((current) => current.includes(id) ? current.filter((value) => value !== id) : [...current, id]);
  const exportSelection = () => {
    const rows = [['Order ID', 'Customer', 'Salesperson', 'Amount', 'Paid', 'Remaining', 'Payment Status', 'Order Status', 'Date']];
    (selected.length ? filtered.filter((order) => selected.includes(order.id)) : filtered).forEach((order) => rows.push([order.id, customerById(order.customerId)?.name || '', userById(order.salespersonId)?.name || '', String(order.total), String(order.paidAmount), String(order.remainingAmount), paymentStatus(order), order.status, formatDate(order.orderDate)]));
    const url = URL.createObjectURL(new Blob([`\ufeff${rows.map((row) => row.map(csvCell).join(',')).join('\r\n')}`], { type: 'text/csv;charset=utf-8' })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'orders.csv'; anchor.click(); URL.revokeObjectURL(url);
  };
  const setFilter = (key: keyof OrderFilters, value: string) => setDraftFilters((current) => ({ ...current, [key]: value }));
  const isSelectedAll = selected.length === filtered.length && filtered.length > 0;
  const handoffs = deals.filter((deal) => deal.stage === 'WON' && !orders.some((order) => order.sourceDealHandoffId === (deal.orderHandoff?.id || deal.id)));

  return <div className="space-y-5">
    <div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><h1 className="text-2xl font-bold tracking-tight text-slate-900 dark:text-white">Orders</h1><p className="text-sm text-slate-500 dark:text-slate-400">Manage order fulfillment, balances, and customer handoffs.</p></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={onAddCustomer}><UserRound className="mr-1.5 h-4 w-4" />Add customer</Button><Button size="sm" variant="outline" onClick={() => { if (selected.length === 1) { const order = orders.find((item) => item.id === selected[0]); if (order) updateOrder(order.id, { invoiceReferences: [{ id: `INV-DRAFT-${Date.now()}`, amount: order.remainingAmount, status: 'DRAFT', createdAt: new Date() }, ...order.invoiceReferences] }, { type: 'INVOICE_CREATED', description: 'Draft invoice reference created' }); } else toast.info('Select one order to create a draft invoice reference'); }}><FileText className="mr-1.5 h-4 w-4" />Create invoice</Button><Button size="sm" variant="outline" onClick={() => { if (selected.length === 1) { const order = orders.find((item) => item.id === selected[0]); if (order) setPaymentOrder(order); } else toast.info('Select one order to record a payment'); }}><Banknote className="mr-1.5 h-4 w-4" />Record payment</Button><Button size="sm" onClick={openNew}><Plus className="mr-1.5 h-4 w-4" />New order</Button></div></div>

    <div className="grid grid-cols-2 gap-3 lg:grid-cols-4 2xl:grid-cols-8"><Metric label="Total orders" value={String(metrics.total)} detail="All order records" icon={ShoppingBag} tone="bg-indigo-50 text-indigo-700 dark:bg-indigo-950 dark:text-indigo-300" /><Metric label="New orders" value={String(metrics.newCount)} detail="Draft and pending" icon={Plus} tone="bg-cyan-50 text-cyan-700 dark:bg-cyan-950 dark:text-cyan-300" /><Metric label="Processing" value={String(metrics.processing)} detail="Confirmed through ready" icon={Activity} tone="bg-blue-50 text-blue-700 dark:bg-blue-950 dark:text-blue-300" /><Metric label="Completed" value={String(metrics.completed)} detail="Fulfilled orders" icon={PackageCheck} tone="bg-emerald-50 text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300" /><Metric label="Pending" value={String(metrics.pending)} detail="Awaiting confirmation" icon={Clock3} tone="bg-amber-50 text-amber-700 dark:bg-amber-950 dark:text-amber-300" /><Metric label="Cancelled" value={String(metrics.cancelled)} detail="Cancellation retained" icon={X} tone="bg-rose-50 text-rose-700 dark:bg-rose-950 dark:text-rose-300" /><Metric label="Total order value" value={MONEY(metrics.value)} detail="All statuses" icon={CircleDollarSign} tone="bg-violet-50 text-violet-700 dark:bg-violet-950 dark:text-violet-300" /><Metric label="Outstanding" value={MONEY(metrics.outstanding)} detail="Remaining balance" icon={Wallet} tone="bg-orange-50 text-orange-700 dark:bg-orange-950 dark:text-orange-300" /></div>

    <div className="grid grid-cols-1 gap-4 xl:grid-cols-3"><Card className="xl:col-span-2"><CardContent className="p-4"><div className="mb-2 flex items-center justify-between"><div><h2 className="text-sm font-semibold">Order analytics</h2><p className="text-xs text-slate-500">Order volume and value by month</p></div><select aria-label="Analytics date range" value={dateRange} onChange={(event) => setDateRange(event.target.value as typeof dateRange)} className="h-8 rounded-md border border-slate-200 bg-white px-2 text-xs dark:border-slate-800 dark:bg-slate-900">{[['7d', '7 days'], ['30d', '30 days'], ['3m', '3 months'], ['6m', '6 months'], ['1y', '1 year']].map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></div><div className="h-48"><ResponsiveContainer width="100%" height="100%"><LineChart data={analytics.byMonth}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="month" tick={{ fontSize: 10 }} /><YAxis yAxisId="count" tick={{ fontSize: 9 }} /><YAxis yAxisId="amount" orientation="right" tick={{ fontSize: 9 }} /><Tooltip formatter={(value, name) => [name === 'Order value' ? MONEY(Number(value || 0)) : String(value ?? ''), String(name ?? '')]} /><Line yAxisId="count" dataKey="count" name="Orders" stroke="#6366f1" strokeWidth={2} /><Line yAxisId="amount" dataKey="value" name="Order value" stroke="#10b981" strokeWidth={2} /></LineChart></ResponsiveContainer></div><div className="flex justify-between border-t border-slate-100 pt-2 text-xs dark:border-slate-800"><span className="text-slate-500">Average order value · {analytics.recentCount} in range</span><strong>{MONEY(analytics.average)}</strong></div></CardContent></Card><Card><CardContent className="p-4"><h2 className="text-sm font-semibold">Order outcomes</h2><p className="text-xs text-slate-500">Completed vs cancelled</p><div className="h-28"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={analytics.statuses} dataKey="value" nameKey="name" innerRadius={28} outerRadius={48}>{analytics.statuses.map((item, index) => <Cell key={item.name} fill={index ? '#f43f5e' : '#10b981'} />)}</Pie><Tooltip /></PieChart></ResponsiveContainer></div><div className="flex justify-between text-xs"><span className="text-emerald-600">Completed {metrics.completed}</span><span className="text-rose-600">Cancelled {metrics.cancelled}</span></div><div className="mt-2 border-t border-slate-100 pt-2 dark:border-slate-800"><p className="mb-1 text-xs text-slate-500">Payment status</p><div className="flex flex-wrap gap-1">{analytics.payments.map((item) => <Badge key={item.name} variant="outline">{item.name} {item.value}</Badge>)}</div></div></CardContent></Card></div>

    {handoffs.length > 0 && <Card><CardHeader className="pb-3"><CardTitle className="text-base">Won deals ready for order</CardTitle></CardHeader><CardContent className="flex flex-wrap gap-2">{handoffs.map((deal) => <div key={deal.id} className="flex flex-wrap items-center gap-2 rounded-md border border-emerald-200 bg-emerald-50/60 p-3 dark:border-emerald-900 dark:bg-emerald-950/20"><span className="text-sm font-medium">{deal.title}</span><span className="text-xs text-slate-500">{MONEY(deal.orderHandoff?.amount || deal.value)}</span><Button size="sm" onClick={() => { setEditingOrder(null); setSeedDeal(deal); setFormOpen(true); }}>Create order</Button></div>)}</CardContent></Card>}

    <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div className="relative w-full lg:max-w-md"><Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-400" /><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search order, customer, company, deal, email, or phone" className="pl-9" /></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => setFilterOpen((value) => !value)}><Filter className="mr-1 h-4 w-4" />Filters{Object.values(filters).filter(Boolean).length > 0 && <Badge className="ml-2">{Object.values(filters).filter(Boolean).length}</Badge>}</Button><Button size="sm" variant="outline" onClick={exportSelection}><Download className="mr-1 h-4 w-4" />Export CSV</Button></div></div>

    {filterOpen && <Card><CardContent className="p-4"><div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4"><Select value={draftFilters.status} onChange={(event) => setFilter('status', event.target.value)}><option value="">Any order status</option>{Object.entries(statusLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</Select><Select value={draftFilters.payment} onChange={(event) => setFilter('payment', event.target.value)}><option value="">Any payment status</option>{Object.entries(paymentLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</Select><Select value={draftFilters.customer} onChange={(event) => setFilter('customer', event.target.value)}><option value="">Any customer</option>{customers.map((customer) => <option key={customer.id} value={customer.id}>{customer.name}</option>)}</Select><Select value={draftFilters.salesperson} onChange={(event) => setFilter('salesperson', event.target.value)}><option value="">Any salesperson</option>{users.map((user) => <option key={user.id} value={user.id}>{user.name}</option>)}</Select><div className="flex gap-2"><Input type="date" aria-label="Date from" value={draftFilters.dateFrom} onChange={(event) => setFilter('dateFrom', event.target.value)} /><Input type="date" aria-label="Date to" value={draftFilters.dateTo} onChange={(event) => setFilter('dateTo', event.target.value)} /></div><div className="flex gap-2"><Input type="number" min="0" placeholder="Min amount" value={draftFilters.minAmount} onChange={(event) => setFilter('minAmount', event.target.value)} /><Input type="number" min="0" placeholder="Max amount" value={draftFilters.maxAmount} onChange={(event) => setFilter('maxAmount', event.target.value)} /></div><Select value={draftFilters.delivery} onChange={(event) => setFilter('delivery', event.target.value)}><option value="">Any delivery status</option>{Object.entries(deliveryLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</Select></div><div className="mt-3 flex justify-end gap-2"><Button size="sm" variant="outline" onClick={() => { setDraftFilters(EMPTY_FILTERS); setFilters(EMPTY_FILTERS); }}>Clear filters</Button><Button size="sm" onClick={() => setFilters(draftFilters)}>Apply filters</Button></div></CardContent></Card>}

    {selected.length > 0 && <div className="flex flex-wrap items-center gap-2 rounded-lg border border-indigo-200 bg-indigo-50 p-3 dark:border-indigo-900 dark:bg-indigo-950/30"><span className="mr-auto text-sm font-semibold">{selected.length} selected</span><Select aria-label="Bulk order status" onChange={(event) => setBulkStatus(event.target.value)} value={bulkStatus}><option value="">Change status</option>{Object.entries(statusLabels).filter(([status]) => ['PENDING', 'CONFIRMED', 'PROCESSING', 'READY', 'COMPLETED'].includes(status)).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</Select><Button size="sm" variant="outline" disabled={!bulkStatus} onClick={() => { const blocked = filtered.filter((order) => selected.includes(order.id)).some((order) => !getNextOrderStatuses(order.status).includes(bulkStatus as OrderStatus)); if (blocked) { toast.info('Some selected orders cannot make this status transition'); return; } if (!window.confirm(`Change status for ${selected.length} orders?`)) return; const now = new Date(); onOrdersChange(orders.map((order) => selected.includes(order.id) ? { ...order, status: bulkStatus as OrderStatus, updatedAt: now, lastActivityAt: now, activities: [{ id: `oa_${now.getTime()}_${order.id}`, type: 'UPDATED', description: `Bulk status changed to ${statusLabels[bulkStatus as OrderStatus]}`, user: currentUser.name, createdAt: now }, ...order.activities] } : order)); setSelected([]); setBulkStatus(''); }}>Apply</Button><Button size="sm" variant="outline" onClick={() => { setCancelReason(''); setCancelNotes(''); setBulkCancelOpen(true); }}>Cancel selected</Button><Button size="icon" variant="ghost" title="Clear selection" onClick={() => setSelected([])}><X className="h-4 w-4" /></Button></div>}

    {error ? <div className="rounded-lg border border-rose-200 bg-rose-50 p-8 text-center text-sm text-rose-700">Orders could not be loaded. {error}</div> : isLoading ? <div className="flex h-40 items-center justify-center rounded-lg border border-slate-200 text-sm text-slate-400"><span className="mr-2 h-4 w-4 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent" />Loading orders...</div> : orders.length === 0 ? <Empty text="No orders yet. Create an order or convert a won deal handoff." action="New order" onAction={openNew} /> : filtered.length === 0 ? <Empty text="No orders match your search and filters." /> : <div className="overflow-x-auto rounded-lg border border-slate-200 dark:border-slate-800"><table className="w-full min-w-260 text-left text-sm"><thead className="bg-slate-50 text-xs uppercase text-slate-500 dark:bg-slate-800"><tr><th className="p-3"><input aria-label="Select all orders" type="checkbox" checked={isSelectedAll} onChange={() => setSelected(isSelectedAll ? [] : filtered.map((order) => order.id))} /></th>{['Order ID', 'Customer', 'Company', 'Deal', 'Salesperson', 'Order amount', 'Paid', 'Remaining', 'Payment status', 'Order status', 'Order date', 'Expected delivery', 'Actions'].map((header) => <th key={header} className="whitespace-nowrap px-3 py-3 font-medium">{header}</th>)}</tr></thead><tbody className="divide-y divide-slate-100 dark:divide-slate-800">{filtered.map((order) => <tr key={order.id} className="hover:bg-slate-50/70 dark:hover:bg-slate-800/40"><td className="p-3"><input aria-label={`Select ${order.id}`} type="checkbox" checked={selected.includes(order.id)} onChange={() => toggleSelect(order.id)} /></td><td><button onClick={() => onNavigate('/orders/detail', order.id)} className="font-semibold text-indigo-600 hover:underline">{order.id}</button></td><td>{customerById(order.customerId)?.name || 'Unknown customer'}</td><td>{order.company || customerById(order.customerId)?.company || '—'}</td><td>{dealById(order.dealId)?.title || '—'}</td><td>{userById(order.salespersonId)?.name || 'Unassigned'}</td><td className="font-semibold">{MONEY(order.total)}</td><td>{MONEY(order.paidAmount)}</td><td className={order.remainingAmount ? 'font-semibold text-rose-600' : ''}>{MONEY(order.remainingAmount)}</td><td><Badge variant={paymentVariant(paymentStatus(order))}>{paymentLabels[paymentStatus(order)]}</Badge></td><td><Badge variant={statusVariant(order.status)}>{statusLabels[order.status]}</Badge></td><td>{formatDate(order.orderDate)}</td><td>{order.expectedDelivery ? formatDate(order.expectedDelivery) : '—'}</td><td><div className="flex items-center gap-1"><Button size="icon" variant="ghost" title="View order" onClick={() => onNavigate('/orders/detail', order.id)}><ChevronRight className="h-4 w-4" /></Button><Button size="icon" variant="ghost" title="Edit order" onClick={() => beginEdit(order)}><Pencil className="h-4 w-4" /></Button><details className="relative"><summary className="grid h-9 w-9 cursor-pointer list-none place-items-center rounded-md text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800"><Activity className="h-4 w-4" /></summary><div className="absolute right-0 z-20 mt-1 w-44 rounded-md border border-slate-200 bg-white p-1 shadow-lg dark:border-slate-700 dark:bg-slate-900"><button onClick={() => duplicateOrder(order)} className="menu-item">Duplicate</button><button onClick={() => { setNoteOrder(order); setNoteText(''); setEditingNoteId(null); onNavigate('/orders/detail', order.id); }} className="menu-item">Add note</button><button onClick={() => { setPaymentOrder(order); setPaymentAmount(''); }} className="menu-item">Record payment</button><button onClick={() => { updateOrder(order.id, { invoiceReferences: [{ id: `INV-DRAFT-${Date.now()}`, amount: order.remainingAmount, status: 'DRAFT', createdAt: new Date() }, ...order.invoiceReferences] }, { type: 'INVOICE_CREATED', description: 'Draft invoice reference created' }); }} className="menu-item">Create invoice</button>{!['CANCELLED', 'COMPLETED', 'REFUNDED'].includes(order.status) && <button onClick={() => confirmCancel(order)} className="menu-item text-rose-600">Cancel order</button>}</div></details></div></td></tr>)}</tbody></table><div className="border-t border-slate-100 px-4 py-2 text-xs text-slate-500 dark:border-slate-800">Showing {filtered.length} of {orders.length} orders</div></div>}

    <OrderForm open={formOpen} onOpenChange={(open) => { setFormOpen(open); if (!open) { setEditingOrder(null); setSeedDeal(null); setDuplicateSeed(null); } }} order={editingOrder || duplicateSeed} customers={customers} deals={deals} users={users} currentUser={currentUser} seedDeal={seedDeal} onSubmit={editingOrder ? saveOrderEdit : saveNewOrder} />
    {bulkCancelOpen && <Dialog open onOpenChange={setBulkCancelOpen}><DialogContent><DialogHeader onClose={() => setBulkCancelOpen(false)}><DialogTitle>Cancel selected orders</DialogTitle><DialogDescription>All selected eligible orders will be cancelled and their history retained.</DialogDescription></DialogHeader><Field label="Cancellation reason *"><Select value={cancelReason} onChange={(event) => setCancelReason(event.target.value)}><option value="">Select reason</option>{['Customer Request', 'Payment Issue', 'Stock/Availability', 'Duplicate Order', 'Other'].map((reason) => <option key={reason}>{reason}</option>)}</Select></Field><Field label="Additional notes"><textarea rows={3} value={cancelNotes} onChange={(event) => setCancelNotes(event.target.value)} className="w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm dark:border-slate-800 dark:bg-slate-900" /></Field><DialogFooter><Button variant="outline" onClick={() => setBulkCancelOpen(false)}>Keep orders</Button><Button variant="destructive" disabled={!cancelReason} onClick={() => { const now = new Date(); onOrdersChange(orders.map((order) => selected.includes(order.id) && !['COMPLETED', 'CANCELLED', 'REFUNDED'].includes(order.status) ? { ...order, status: 'CANCELLED', cancellationReason: cancelReason, cancellationNotes: cancelNotes, updatedAt: now, lastActivityAt: now, activities: [{ id: `oa_${now.getTime()}_${order.id}`, type: 'CANCELLED', description: `Order cancelled: ${cancelReason}`, user: currentUser.name, createdAt: now }, ...order.activities] } : order)); setSelected([]); setBulkCancelOpen(false); }}>Confirm cancellation</Button></DialogFooter></DialogContent></Dialog>}
    {noteOrder && <Dialog open onOpenChange={(open) => { if (!open) setNoteOrder(null); }}><DialogContent><DialogHeader onClose={() => setNoteOrder(null)}><DialogTitle>Add order note</DialogTitle><DialogDescription>Notes are stored on the order record.</DialogDescription></DialogHeader><textarea rows={4} value={noteText} onChange={(event) => setNoteText(event.target.value)} className="w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm dark:border-slate-800 dark:bg-slate-900" /><DialogFooter><Button variant="outline" onClick={() => setNoteOrder(null)}>Cancel</Button><Button disabled={!noteText.trim()} onClick={() => { const now = new Date(); updateOrder(noteOrder.id, { notes: [{ id: `on_${Date.now()}`, content: noteText.trim(), author: currentUser.name, createdAt: now }, ...noteOrder.notes] }, { type: 'NOTE_ADDED', description: 'Order note added' }); setNoteOrder(null); setNoteText(''); }}>Add note</Button></DialogFooter></DialogContent></Dialog>}
    {paymentOrder && <Dialog open onOpenChange={(open) => { if (!open) setPaymentOrder(null); }}><DialogContent><DialogHeader onClose={() => setPaymentOrder(null)}><DialogTitle>Record payment · {paymentOrder.id}</DialogTitle><DialogDescription>Remaining balance {MONEY(paymentOrder.remainingAmount)}.</DialogDescription></DialogHeader><Field label="Amount"><Input type="number" min="0.01" max={paymentOrder.remainingAmount} step="0.01" value={paymentAmount} onChange={(event) => setPaymentAmount(event.target.value)} /></Field><Field label="Method"><Select value={paymentMethod} onChange={(event) => setPaymentMethod(event.target.value)}>{['Bank transfer', 'Credit card', 'Cash', 'Check', 'Other'].map((method) => <option key={method}>{method}</option>)}</Select></Field><Field label="Transaction reference"><Input value={paymentTransaction} onChange={(event) => setPaymentTransaction(event.target.value)} /></Field><DialogFooter><Button variant="outline" onClick={() => setPaymentOrder(null)}>Cancel</Button><Button disabled={!paymentAmount || Number(paymentAmount) <= 0 || Number(paymentAmount) > paymentOrder.remainingAmount} onClick={() => { const now = new Date(); const amount = Number(paymentAmount); const paidAmount = paymentOrder.paidAmount + amount; const totals = calculateOrderTotals(paymentOrder.items, paymentOrder.additionalCharges, paidAmount); updateOrder(paymentOrder.id, { ...totals, paymentStatus: getPaymentStatus(paymentOrder.total, paidAmount), lastPaymentDate: now, paymentReferences: [{ id: `PAY-LOCAL-${Date.now()}`, amount, method: paymentMethod, transactionId: paymentTransaction, status: 'RECORDED', paidAt: now }, ...paymentOrder.paymentReferences] }, { type: 'PAYMENT_RECEIVED', description: `${MONEY(amount)} payment recorded` }); setPaymentOrder(null); }}>Record payment</Button></DialogFooter></DialogContent></Dialog>}
    {cancelOrder && <Dialog open onOpenChange={(open) => { if (!open) setCancelOrder(null); }}><DialogContent><DialogHeader onClose={() => setCancelOrder(null)}><DialogTitle>Cancel order · {cancelOrder.id}</DialogTitle><DialogDescription>Cancellation reason is required. Order history will be preserved.</DialogDescription></DialogHeader><Field label="Cancellation reason *"><Select value={cancelReason} onChange={(event) => setCancelReason(event.target.value)}><option value="">Select reason</option>{['Customer Request', 'Payment Issue', 'Stock/Availability', 'Duplicate Order', 'Other'].map((reason) => <option key={reason}>{reason}</option>)}</Select></Field><Field label="Additional notes"><textarea rows={3} value={cancelNotes} onChange={(event) => setCancelNotes(event.target.value)} className="w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm dark:border-slate-800 dark:bg-slate-900" /></Field><DialogFooter><Button variant="outline" onClick={() => setCancelOrder(null)}>Keep order</Button><Button variant="destructive" disabled={!cancelReason} onClick={() => { const now = new Date(); onOrdersChange(orders.map((order) => order.id !== cancelOrder.id ? order : { ...order, status: 'CANCELLED', cancellationReason: cancelReason, cancellationNotes: cancelNotes, updatedAt: now, lastActivityAt: now, activities: [{ id: `oa_${now.getTime()}`, type: 'CANCELLED', description: `Order cancelled: ${cancelReason}`, user: currentUser.name, createdAt: now }, ...order.activities] })); setCancelOrder(null); }}>Confirm cancellation</Button></DialogFooter></DialogContent></Dialog>}
    {bulkCancelOpen && <Dialog open onOpenChange={setBulkCancelOpen}><DialogContent><DialogHeader onClose={() => setBulkCancelOpen(false)}><DialogTitle>Cancel selected orders</DialogTitle><DialogDescription>Eligible selected orders will be cancelled with the same reason. Completed orders cannot be bulk-cancelled.</DialogDescription></DialogHeader><Field label="Cancellation reason *"><Select value={cancelReason} onChange={(event) => setCancelReason(event.target.value)}><option value="">Select reason</option>{['Customer Request', 'Payment Issue', 'Stock/Availability', 'Duplicate Order', 'Other'].map((reason) => <option key={reason}>{reason}</option>)}</Select></Field><Field label="Additional notes"><textarea rows={3} value={cancelNotes} onChange={(event) => setCancelNotes(event.target.value)} className="w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm dark:border-slate-800 dark:bg-slate-900" /></Field><DialogFooter><Button variant="outline" onClick={() => setBulkCancelOpen(false)}>Keep orders</Button><Button variant="destructive" disabled={!cancelReason || filtered.filter((order) => selected.includes(order.id)).some((order) => ['COMPLETED', 'CANCELLED', 'REFUNDED'].includes(order.status))} onClick={() => { const now = new Date(); onOrdersChange(orders.map((order) => !selected.includes(order.id) ? order : { ...order, status: 'CANCELLED', cancellationReason: cancelReason, cancellationNotes: cancelNotes, updatedAt: now, lastActivityAt: now, activities: [{ id: `oa_${now.getTime()}_${order.id}`, type: 'CANCELLED', description: `Order cancelled: ${cancelReason}`, user: currentUser.name, createdAt: now }, ...order.activities] })); setSelected([]); setBulkCancelOpen(false); }}>Confirm cancellation</Button></DialogFooter></DialogContent></Dialog>}
  </div>;
}

function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="block min-w-0 space-y-1 text-xs font-medium text-slate-600 dark:text-slate-300"><span>{label}</span>{children}</label>; }
function Pair({ label, value, bold = false }: { label: string; value: string; bold?: boolean }) { return <div className="flex justify-between gap-3"><span className="text-slate-500">{label}</span><span className={bold ? 'font-bold' : ''}>{value}</span></div>; }
function Summary({ label, value, icon: Icon }: { label: string; value: string; icon: React.ElementType }) { return <Card><CardContent className="flex items-center gap-2.5 p-3"><span className="rounded-md bg-slate-100 p-2 text-slate-600 dark:bg-slate-800"><Icon className="h-4 w-4" /></span><div><p className="text-[11px] text-slate-500">{label}</p><p className="text-base font-semibold">{value}</p></div></CardContent></Card>; }
function Empty({ text, action, onAction }: { text: string; action?: string; onAction?: () => void }) { return <div className="rounded-lg border border-dashed border-slate-200 px-4 py-10 text-center text-sm text-slate-500 dark:border-slate-800">{text}{action && onAction && <div><Button className="mt-3" size="sm" onClick={onAction}><Plus className="mr-1 h-4 w-4" />{action}</Button></div>}</div>; }
function SimpleTable({ headers, rows, empty }: { headers: string[]; rows: React.ReactNode[][]; empty: string }) { return rows.length ? <div className="overflow-x-auto rounded-md border border-slate-200 dark:border-slate-800"><table className="w-full min-w-180 text-left text-sm"><thead className="bg-slate-50 text-xs uppercase text-slate-500 dark:bg-slate-800"><tr>{headers.map((header) => <th key={header} className="whitespace-nowrap px-3 py-3 font-medium">{header}</th>)}</tr></thead><tbody className="divide-y divide-slate-100 dark:divide-slate-800">{rows.map((row, index) => <tr key={index}>{row.map((cell, cellIndex) => <td key={cellIndex} className="whitespace-nowrap px-3 py-3">{cell}</td>)}</tr>)}</tbody></table></div> : <Empty text={empty} />; }
function Timeline({ events }: { events: OrderActivity[] }) { return events.length ? <div className="space-y-3">{events.map((event) => <div key={event.id} className="flex gap-3 border-b border-slate-100 pb-3 last:border-0 dark:border-slate-800"><span className="grid h-8 w-8 shrink-0 place-items-center rounded-full bg-indigo-50 text-indigo-600 dark:bg-indigo-950 dark:text-indigo-300"><Activity className="h-4 w-4" /></span><div><p className="text-sm font-medium">{event.description}</p><p className="mt-1 text-xs text-slate-400">{event.user} · {new Date(event.createdAt).toLocaleString()}</p></div></div>)}</div> : <Empty text="No order activity." />; }
export default OrderWorkspace;
